import java.util.*;

class StockSpanner {
    private Deque<int[]> st;   // each entry: {price, streak}, prices decreasing

    public StockSpanner() {
        st = new ArrayDeque<>();
    }

    public int next(int price) {
        int streak = 1;
        while (!st.isEmpty() && st.peek()[0] <= price) streak += st.pop()[1];  // absorb smaller days
        st.push(new int[]{price, streak});
        return streak;
    }
}

